import XCTest

final class UpdatesTests: XCTestCase {
    func testInfoPlistHasFeedAndKey() throws {
        // app/Tests/UpdatesTests.swift -> app/Info.plist (generated by xcodegen)
        let plist = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().appendingPathComponent("Info.plist")
        let data = try Data(contentsOf: plist)
        let info = try XCTUnwrap(
            PropertyListSerialization.propertyList(from: data, format: nil) as? [String: Any])

        XCTAssertEqual(
            info["SUFeedURL"] as? String,
            "https://github.com/matthieuh/balance-ton-port/releases/latest/download/appcast.xml")
        let key = try XCTUnwrap(info["SUPublicEDKey"] as? String)
        XCTAssertEqual(key.count, 44)
        XCTAssertNotNil(Data(base64Encoded: key))
        XCTAssertEqual(info["SUScheduledCheckInterval"] as? Int, 86400)
        XCTAssertEqual(info["SUEnableSystemProfiling"] as? Bool, false)
    }

    func testAppVersionString() {
        XCTAssertEqual(
            UpdateController.appVersion(["CFBundleShortVersionString": "0.5.0", "CFBundleVersion": "7"]),
            "0.5.0 (7)")
    }
}
